16	/**
17	 * First step of {@code POST /api/owners}. Rejects a create whose firstName, lastName,
18	 * address, city or telephone is missing or blank before {@link BuildOwner} maps the body,
19	 * so an incomplete request is a 400 listing each field rather than a persisted owner. The
20	 * address may be supplied in structured form (a non-blank {@code addressLine1}, an optional
21	 * {@code addressLine2}) or as the flat {@code address}; the structured form is preferred and the
22	 * canonical {@code address} is composed from it (normalized addressLine1, plus a single space and
23	 * the normalized addressLine2 when present). An owner is valid when it supplies an address in
24	 * either form, plus a city.
25	 * Also normalizes the telephone to E.164 form (see {@link TelephoneE164}), storing the E.164
26	 * value on the body and rejecting a number that cannot form a valid E.164 string. An optional
27	 * email, when present, must be a syntactically valid address and is stored lower-cased.
28	 * Publishes the validated body for the later steps.
29	 */
30	public class RequireOwnerFields {
31	
32	    /** Pragmatic syntactic check: one or more non-space/@ characters, an '@', a domain label,
33	     *  a dot, and a top-level label. Rejects inputs such as "not-an-email". */
34	    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
35	
36	    /** Disposable/throwaway email domains a create-owner request may not use. */
37	    private static final Set<String> DISPOSABLE_DOMAINS =
